mod solution;

fn main() {
    let cases = [
    (r#"n=4 edges=(0,1),(1,2),(1,3)"#, r#"5,3,5,5"#),
    (r#"n=3 edges=(0,1),(1,2)"#, r#"3,2,3"#),
    (r#"
n=3 edges=(0,1),(1,2)
"#, r#"3,2,3"#),
    (r#"  
n=4 edges=(0,1),(1,2),(1,3)
  "#, r#"5,3,5,5"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS tree-rerooting");
}
